insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_tt1_v1'
from (values
('117.323.c.1.A',2,'In a stage shop, what is a ''flat''?','["A wooden-framed, covered panel used as scenery", "A type of microphone", "A box office report", "A costume undergarment"]'::jsonb,0,'Flats are basic scenic units.','original'),
('117.323.c.1.A',2,'A ''gel'' is a colored sheet placed in front of a ___.','["Sewing machine", "Stage light", "Microphone", "Door lock"]'::jsonb,1,'Gels color light.','original'),
('117.323.c.1.B',2,'Which stage type has the audience seated on three sides of the playing area?','["Black box with seats in one row", "Orchestra pit", "Thrust stage", "Proscenium stage"]'::jsonb,2,'A thrust stage projects into the audience.','original'),
('117.323.c.1.B',2,'The fly system is used to ___.','["Seat audience members", "Mix colors for makeup", "Cook meals", "Raise and lower scenery and equipment above the stage"]'::jsonb,3,'Fly systems move items overhead.','original'),
('117.323.c.1.C',2,'A production calendar is used to ___.','["Schedule rehearsals, builds and performance dates", "Choose paint colors only", "Rate audience members", "Sell concessions"]'::jsonb,0,'Calendars organize deadlines.','original'),
('117.323.c.1.C',2,'What happens at a technical rehearsal?','["Casting auditions", "Cast and crew run cues for lights, sound and scenery changes", "Costume shopping", "Program printing"]'::jsonb,1,'Tech rehearsals integrate technical elements.','original'),
('117.323.c.1.D',2,'Before using a power saw in the shop, a student should ___.','["Remove the guard", "Wear loose sleeves", "Wear eye protection and get approval from the shop supervisor", "Work alone at night"]'::jsonb,2,'Tool safety starts with PPE and supervision.','original'),
('117.323.c.1.D',2,'Why must exit paths backstage stay clear?','["To store more props", "To save electricity", "To make the room look larger", "So people can leave quickly in a fire or emergency"]'::jsonb,3,'Fire safety requires clear exits.','original'),
('117.323.c.1.E',3,'When reading a script for technical needs, a student underlines every mention of sounds, such as a doorbell. She is making a list of ___.','["Sound cues", "Rehearsal snacks", "Tickets", "Costume repairs"]'::jsonb,0,'Scripts reveal technical requirements.','original'),
('117.323.c.1.E',3,'A stage direction says ''Night. Moonlight enters through the window.'' This tells the lighting designer about ___.','["The ticket price", "Time of day and the type of light needed", "The actor''s age", "The program fonts"]'::jsonb,1,'Directions give lighting clues.','original'),
('117.323.c.2.A',3,'A realistic living-room play and an abstract dance piece would likely use ___ scenery.','["Only digital", "No", "Different styles of", "Identical"]'::jsonb,2,'Style shapes technical choices.','original'),
('117.323.c.2.A',3,'In a fantasy genre production, which technical element often supports the world of the story?','["A parking sign", "A grocery receipt", "A lobby chair", "Special lighting, costumes and scenery that suggest a magical setting"]'::jsonb,3,'Technical elements support genre.','original'),
('117.323.c.2.B',3,'Which order best lists the steps of the design process?','["Analysis, research, incubation/selection, implementation, evaluation", "Selection, evaluation, research, analysis", "Evaluation, implementation, analysis, research", "Research, evaluation, selection, analysis"]'::jsonb,0,'The process begins with analysis and ends with evaluation.','original'),
('117.323.c.2.B',3,'During the ''research'' step of design, a student might ___.','["Strike the show", "Collect images and facts about the play''s time and place", "Sell tickets", "Paint the final set"]'::jsonb,1,'Research informs design.','original'),
('117.323.c.2.C',2,'Who is in charge of coordinating all aspects of a production and communicating the vision?','["The janitor", "The usher", "The director", "The caterer"]'::jsonb,2,'Directors guide the vision.','original'),
('117.323.c.2.C',2,'Which member of the production team calls cues during a performance?','["Playwright", "Costume buyer", "House painter", "Stage manager"]'::jsonb,3,'Stage managers call cues.','original'),
('117.323.c.2.D',3,'A scenic designer and lighting designer talk before the build so the paint colors and lights work together. This shows ___.','["Collaboration", "Delay", "Isolation", "Competition"]'::jsonb,0,'Teamwork prevents conflicts.','original'),
('117.323.c.2.D',3,'A crew head assigns tasks, checks progress and encourages teammates. She is showing ___.','["Avoidance", "Leadership", "Hesitation", "Mockery"]'::jsonb,1,'Leaders organize and support.','original'),
('117.323.c.2.E',3,'A student chooses a color palette for a costume that shows a character''s mood. This is ___ in design.','["A safety violation", "Plagiarism", "Creative personal expression", "Accounting"]'::jsonb,2,'Creativity shapes design choices.','original'),
('117.323.c.2.E',3,'Which choice shows creativity in prop design?','["Copying a catalog item exactly", "Leaving the stage empty", "Ignoring the script", "Building an original prop that fits the story"]'::jsonb,3,'Original solutions show creativity.','original'),
('117.323.c.2.F',3,'A designer gives the director a rendering and a swatch board for the costumes. These are ways to ___.','["Communicate design ideas", "Cancel the show", "Hide the design", "Sell tickets"]'::jsonb,0,'Renderings and swatches communicate ideas.','original'),
('117.323.c.2.F',3,'A prompt book is a ___.','["Menu for the cast party", "Script with blocking, cues and notes used to run the show", "Poster collection", "List of audience members"]'::jsonb,1,'The prompt book guides the performance.','original'),
('117.323.c.2.G',2,'A carpenter measures a board that is 8 feet long and needs two pieces of 3 feet each. How much is left over?','["1 foot", "3 feet", "2 feet", "5 feet"]'::jsonb,2,'8 − (3 + 3) = 2.','original'),
('117.323.c.2.G',2,'Which tool is used to measure a length for a scenery board?','["A thermostat", "A metronome", "A voltmeter", "A tape measure"]'::jsonb,3,'Tape measures give length.','original'),
('117.323.c.3.A',2,'What should you do with a hand saw when you finish a cut?','["Put it back in its proper storage place", "Leave it on the stage floor", "Throw it in a bin", "Hand it to someone blade first"]'::jsonb,0,'Proper storage prevents accidents.','original'),
('117.323.c.3.A',2,'Which item protects a student''s eyes while sanding scenery?','["A scarf", "Safety glasses", "A hat", "A headset"]'::jsonb,1,'Eye protection is required.','original'),
('117.323.c.3.B',3,'Which part of the lighting system raises and lowers brightness?','["Cable tie", "Clamp", "Dimmer", "Gobo"]'::jsonb,2,'Dimmers control intensity.','original'),
('117.323.c.3.B',3,'Before hanging a light, a student should ___.','["Skip the cable", "Climb without a spotter", "Hang it unsupported", "Check the safety cable and clamp and use a safe ladder with a partner"]'::jsonb,3,'Rigging safety is essential.','original'),
('117.323.c.3.C',2,'When applying stage makeup, a performer should ___.','["Use clean tools and avoid sharing products that touch the eyes or mouth", "Skip washing hands", "Use craft glue", "Share eye pencils freely"]'::jsonb,0,'Hygiene prevents infection.','original'),
('117.323.c.3.C',2,'Why use a thimble or pincushion when hand-sewing a costume?','["To dye the cloth", "To protect fingers and keep pins organized", "To shrink the fabric", "To make the thread louder"]'::jsonb,1,'Tools prevent injury.','original'),
('117.323.c.3.D',3,'Which action keeps sound equipment safe?','["Pull on cables", "Pour water on the board", "Keep drinks away from the sound board and tape down cables", "Leave cords in doorways"]'::jsonb,2,'Protect equipment and people.','original'),
('117.323.c.3.D',3,'Why should a sound operator keep volume levels in check?','["To save ink", "To shorten the play", "To change the set", "To protect hearing and equipment"]'::jsonb,3,'Loud sound can damage ears and speakers.','original'),
('117.323.c.3.E',2,'The house manager is responsible for ___.','["Audience seating, safety and the front-of-house operations", "Painting the set", "Calling cues from the booth", "Writing the script"]'::jsonb,0,'House management serves the audience.','original'),
('117.323.c.3.E',2,'Which person keeps the rehearsal and performance running smoothly backstage?','["Parking attendant", "Stage manager", "Concessions clerk", "Playbill printer"]'::jsonb,1,'Stage managers coordinate backstage.','original'),
('117.323.c.4.A',3,'A designer researching a 1920s dress studies photos, fashion magazines and museum collections. She is establishing ___.','["Marketing", "Silly mistakes", "Historical accuracy", "Budget cuts"]'::jsonb,2,'Research ensures accuracy.','original'),
('117.323.c.4.A',3,'Why does cultural accuracy matter in theatrical design?','["It replaces actors", "It removes the need for rehearsal", "It reduces ticket costs", "It respects the culture shown and helps the audience believe the world"]'::jsonb,3,'Accuracy builds respect and credibility.','original'),
('117.323.c.4.B',3,'Compared with live theatre, film allows ___.','["Close-ups and editing that can change the audience''s view instantly", "No sound", "A live audience only", "No story"]'::jsonb,0,'Film uses camera and editing.','original'),
('117.323.c.4.B',3,'Which statement shows the impact of electronic media on theatre?','["Theatre banned electricity", "Projections and digital sound are now used in many live productions", "Theatre removed actors", "Theatre ended"]'::jsonb,1,'Technology is integrated into live shows.','original'),
('117.323.c.4.C',3,'Greek theatre in ancient Athens used masks and an open-air amphitheater. This is part of the ___ of world theatre.','["Press kit", "Parking plan", "Cultural heritage", "Ticket policy"]'::jsonb,2,'World theatre has a rich heritage.','original'),
('117.323.c.4.C',3,'Which key figure is known for plays performed at the Globe Theatre?','["Walt Disney", "Thomas Edison", "Pablo Picasso", "William Shakespeare"]'::jsonb,3,'Shakespeare wrote for the Globe.','original'),
('117.323.c.4.D',3,'The United States contributed major innovations to stage lighting and design. One example is ___.','["Developments in electric stage lighting", "The amphitheater", "The mystery play", "The invention of the mask"]'::jsonb,0,'American theatre advanced electric lighting.','original'),
('117.323.c.4.D',3,'Broadway is known for contributing which form that mixes music, dance and drama?','["Greek chorus", "The American musical", "Commedia dell''arte", "Noh drama"]'::jsonb,1,'The musical is an American innovation.','original'),
('117.323.c.5.A',2,'A technical theatre portfolio usually includes ___.','["Only a program cover", "Only a grocery list", "Photos, drawings and notes showing a student''s design and build work", "Only a ticket"]'::jsonb,2,'Portfolios display work.','original'),
('117.323.c.5.A',2,'A resume for a technical theatre student lists ___.','["Hair color", "Locker number", "Favorite foods", "Experience, skills and productions worked on"]'::jsonb,3,'Resumes summarize experience.','original'),
('117.323.c.5.B',2,'At a live performance, an audience member should ___.','["Silence phones and respect the performers and others", "Talk loudly", "Walk on stage", "Take flash photos"]'::jsonb,0,'Etiquette supports the show.','original'),
('117.323.c.5.B',2,'Behavior at an outdoor theatre festival may differ from a formal theatre because ___.','["There are no rules", "Different venues have different expectations", "Nobody is watching", "Performers don''t matter"]'::jsonb,1,'Context affects etiquette.','original'),
('117.323.c.5.C',3,'A student reflects that a well-lit scene made the actors'' expressions clear. She is evaluating the design as part of an ___.','["Accident", "Mistake", "Art form", "Unplanned event"]'::jsonb,2,'Technical design is an art.','original'),
('117.323.c.5.C',3,'Self-evaluation after building a set helps a student ___.','["Blame others", "Skip tools", "Avoid learning", "Identify what worked and what to improve"]'::jsonb,3,'Reflection improves skill.','original'),
('117.323.c.5.D',3,'A review that describes how the costumes and lighting supported the mood of the play is ___.','["Specific and precise", "Vague", "Off-topic", "Unrelated"]'::jsonb,0,'Specific details support evaluation.','original'),
('117.323.c.5.D',3,'Which sentence evaluates a live play precisely?','["It was okay", "The warm amber lights during the kitchen scene made the family feel close", "I liked it", "Nice show"]'::jsonb,1,'Precise observations name the element and effect.','original'),
('117.323.c.5.E',3,'A student reviews a film and notes how sound design heightened tension in a chase. She is evaluating ___.','["The parking", "The theatre carpet", "A medium with precise observations", "The ticket price"]'::jsonb,2,'Film review can be as precise as theatre review.','original'),
('117.323.c.5.E',3,'When evaluating a TV drama, which comment is specific?','["It was long", "I like TV", "The actors were fine", "The color grading made the flashbacks look faded and distant"]'::jsonb,3,'Specificity shows analysis.','original'),
('117.323.c.5.F',3,'A student who enjoys building scenery learns that carpenters, designers and technicians work in many careers. She is ___ theatre skills to careers.','["Connecting", "Ending", "Ignoring", "Hiding"]'::jsonb,0,'Skills link to careers.','original'),
('117.323.c.5.F',3,'Which skill from technical theatre helps in many careers?','["Ignoring deadlines", "Planning, teamwork and problem solving", "Avoiding tasks", "Skipping safety"]'::jsonb,1,'Skills transfer.','original'),
('117.323.c.5.G',3,'A student posts photos of her light plot and a short explanation on a class website. She is using ___ to present findings.','["A ladder only", "A hammer", "Technology", "A broom"]'::jsonb,2,'Digital tools present information.','original'),
('117.323.c.5.G',3,'A clear slideshow of a technical project should ___.','["Have no order", "Include blurry unlabeled images", "Be a wall of text", "Use labeled images and short, organized text"]'::jsonb,3,'Clarity helps the audience.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
